24	func newDoctorCmd() *cobra.Command {
25		var forceFlag bool
26	
27		cmd := &cobra.Command{
28			Use:   "doctor",
29			Short: "Diagnose and fix session issues",
30			Long: `Scan for session issues and offer to fix them.
31	
32	Checks performed:
33	  1. Disconnected metadata branches: detects when local and remote
34	     entire/checkpoints/v1 branches share no common ancestor (caused by a
35	     previous bug). Fixes by cherry-picking local checkpoints onto remote tip.
36	
37	  When Codex hooks are installed:
38	  2. Codex hook trust: warn when hooks declared in .codex/hooks.json
39	     lack a trusted_hash entry in the user's Codex config (i.e. /hooks
40	     review hasn't run yet on this machine, or a newer entire release
41	     added a hook the user hasn't approved yet).
42	
43	  3. Stuck sessions: sessions stuck in ACTIVE or ENDED phase that need cleanup.
44	
45	A session is considered stuck if:
46	  - It is in ACTIVE phase with no interaction for over 1 hour
47	  - It is in ENDED phase with uncondensed checkpoint data on a shadow branch
48	
49	For each stuck session, you can choose to:
50	  - Condense: Save session data to permanent storage
51	  - Discard: Remove the session state and shadow branch data
52	  - Skip: Leave the session as-is
53	
54	Use --force to condense all fixable sessions without prompting.  Sessions that can't
55	be condensed will be discarded.`,
56			PreRun: func(_ *cobra.Command, _ []string) {
57				strategy.EnsureRedactionConfigured()
58			},
59			RunE: func(cmd *cobra.Command, _ []string) error {
60				return runSessionsFix(cmd, forceFlag)
61			},
62		}
63	
64		cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Auto-fix all issues without prompting")
65	
66		// Diagnostic subcommands.
67		cmd.AddCommand(newTraceCmd())
68		cmd.AddCommand(newDoctorLogsCmd())
69		cmd.AddCommand(newDoctorBundleCmd())
70	
71		return cmd
72	}
