74	// stuckSession holds a session state along with diagnostic info.
75	type stuckSession struct {
76		State             *strategy.SessionState
77		Reason            string
78		ShadowBranch      string
79		HasShadowBranch   bool
80		CheckpointCount   int
81		FilesTouchedCount int
82	}
83	
84	func runSessionsFix(cmd *cobra.Command, force bool) error {
85		var finalErr error
86	
87		// Check 1: Disconnected metadata branches
88		metadataErr := checkDisconnectedMetadata(cmd, force)
89		if metadataErr != nil {
90			fmt.Fprintf(cmd.ErrOrStderr(), "Error: metadata check failed: %v\n", metadataErr)
91			finalErr = NewSilentError(fmt.Errorf("metadata check failed: %w", metadataErr))
92		}
93		fmt.Fprintln(cmd.OutOrStdout())
94	
95		ctx := cmd.Context()
96	
97		// Agent-specific: Codex hook trust state.
98		checkCodexHookTrust(cmd)
99	
100		// Stuck sessions
101		// Load all session states
102		states, err := strategy.ListSessionStates(ctx)
103		if err != nil {
104			return fmt.Errorf("failed to list session states: %w", err)
105		}
106	
107		if len(states) == 0 {
108			fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
109			if finalErr != nil {
110				return finalErr
111			}
112			return nil
113		}
114	
115		// Open repository to check shadow branches (uses worktree-aware helper)
116		repo, err := openRepository(ctx)
117		if err != nil {
118			return fmt.Errorf("failed to open repository: %w", err)
119		}
120		defer repo.Close()
121	
122		// Identify stuck sessions
123		now := time.Now()
124		var stuck []stuckSession
125	
126		for _, state := range states {
127			ss := classifySession(state, repo, now)
128			if ss != nil {
129				stuck = append(stuck, *ss)
130			}
131		}
132	
133		if len(stuck) == 0 {
134			fmt.Fprintln(cmd.OutOrStdout(), "No stuck sessions found.")
135			if finalErr != nil {
136				return finalErr
137			}
138			return nil
139		}
140	
141		// Get the current strategy for condense operations
142		strat := GetStrategy(ctx)
143	
144		fmt.Fprintf(cmd.OutOrStdout(), "Found %d stuck session(s):\n\n", len(stuck))
145	
146		for _, ss := range stuck {
147			displayStuckSession(cmd, ss)
148	
149			if force {
150				if ss.HasShadowBranch && ss.CheckpointCount > 0 {
151					if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
152						fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
153					} else {
154						fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
155					}
156				} else {
157					// Discard if we can't condense
158					if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
159						fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
160					} else {
161						fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
162					}
163				}
164				continue
165			}
166	
167			// Interactive: prompt for action
168			action, err := promptSessionAction(ss)
169			if err != nil {
170				if errors.Is(err, huh.ErrUserAborted) {
171					return nil
172				}
173				return fmt.Errorf("failed to get action: %w", err)
174			}
175	
176			switch action {
177			case "condense":
178				if err := strat.CondenseSessionByID(ctx, ss.State.SessionID); err != nil {
179					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to condense session %s: %v\n", ss.State.SessionID, err)
180				} else {
181					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Condensed session %s\n\n", ss.State.SessionID)
182				}
183			case "discard":
184				if err := discardSession(ctx, ss, repo, cmd.ErrOrStderr()); err != nil {
185					fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to discard session %s: %v\n", ss.State.SessionID, err)
186				} else {
187					fmt.Fprintf(cmd.OutOrStdout(), "  ✓ Discarded session %s\n\n", ss.State.SessionID)
188				}
189			case "skip":
190				fmt.Fprintf(cmd.OutOrStdout(), "  -> Skipped\n\n")
191			}
192		}
193	
194		if finalErr != nil {
195			return finalErr
196		}
197	
198		return nil
199	}
