201	// classifySession determines if a session is stuck and returns diagnostic info.
202	// Returns nil if the session is healthy.
203	func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
204		// Determine shadow branch info
205		shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
206		refName := plumbing.NewBranchReferenceName(shadowBranch)
207		_, refErr := repo.Reference(refName, true)
208		hasShadowBranch := refErr == nil
209	
210		switch {
211		case state.Phase.IsActive():
212			if !state.IsStuckActive() {
213				return nil
214			}
215	
216			var reason string
217			if state.LastInteractionTime != nil {
218				reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
219			} else {
220				reason = fmt.Sprintf("active, started %s ago with no recorded interaction", now.Sub(state.StartedAt).Truncate(time.Minute))
221			}
222	
223			return &stuckSession{
224				State:             state,
225				Reason:            reason,
226				ShadowBranch:      shadowBranch,
227				HasShadowBranch:   hasShadowBranch,
228				CheckpointCount:   state.StepCount,
229				FilesTouchedCount: len(state.FilesTouched),
230			}
231	
232		case state.Phase == session.PhaseEnded:
233			// Ended sessions are stuck if they have uncondensed data
234			if state.StepCount <= 0 || !hasShadowBranch {
235				return nil
236			}
237	
238			return &stuckSession{
239				State:             state,
240				Reason:            "ended with uncondensed checkpoint data",
241				ShadowBranch:      shadowBranch,
242				HasShadowBranch:   hasShadowBranch,
243				CheckpointCount:   state.StepCount,
244				FilesTouchedCount: len(state.FilesTouched),
245			}
246	
247		default:
248			return nil
249		}
250	}
251	
252	// displayStuckSession prints diagnostic info for a stuck session.
253	func displayStuckSession(cmd *cobra.Command, ss stuckSession) {
254		w := cmd.OutOrStdout()
255	
256		fmt.Fprintf(w, "  Session: %s\n", ss.State.SessionID)
257		fmt.Fprintf(w, "  Phase:   %s\n", ss.State.Phase)
258		fmt.Fprintf(w, "  Reason:  %s\n", ss.Reason)
259	
260		if ss.State.AgentType != "" {
261			fmt.Fprintf(w, "  Agent:   %s\n", ss.State.AgentType)
262		}
263	
264		if ss.State.LastInteractionTime != nil {
265			fmt.Fprintf(w, "  Last interaction: %s\n", ss.State.LastInteractionTime.Format(time.RFC3339))
266		}
267	
268		shadowStatus := "not found"
269		if ss.HasShadowBranch {
270			shadowStatus = fmt.Sprintf("exists (%s)", ss.ShadowBranch)
271		}
272		fmt.Fprintf(w, "  Shadow branch: %s\n", shadowStatus)
273		fmt.Fprintf(w, "  Checkpoints: %d, Files touched: %d\n", ss.CheckpointCount, ss.FilesTouchedCount)
274	}
275	
276	// promptSessionAction asks the user what to do with a stuck session.
277	func promptSessionAction(ss stuckSession) (string, error) {
278		var action string
279	
280		options := make([]huh.Option[string], 0, 3)
281		if ss.HasShadowBranch && ss.CheckpointCount > 0 {
282			options = append(options, huh.NewOption("Condense (save to permanent storage)", "condense"))
283		}
284		options = append(options,
285			huh.NewOption("Discard (remove session data)", "discard"),
286			huh.NewOption("Skip (leave as-is)", "skip"),
287		)
288	
289		form := NewAccessibleForm(
290			huh.NewGroup(
291				huh.NewSelect[string]().
292					Title(fmt.Sprintf("Fix session %s?", ss.State.SessionID)).
293					Options(options...).
294					Value(&action),
295			),
296		)
297	
298		if err := form.Run(); err != nil {
299			return "", fmt.Errorf("session fix prompt failed: %w", err)
300		}
301	
302		return action, nil
303	}
304	
305	// discardSession removes session state and cleans up the shadow branch.
306	func discardSession(ctx context.Context, ss stuckSession, _ *git.Repository, errW io.Writer) error {
307		// Clear session state file
308		if err := strategy.ClearSessionState(ctx, ss.State.SessionID); err != nil {
309			return fmt.Errorf("failed to clear session state: %w", err)
310		}
311	
312		// Delete shadow branch if it exists and no other sessions need it
313		if ss.HasShadowBranch {
314			if shouldDelete, err := canDeleteShadowBranch(ctx, ss.ShadowBranch, ss.State.SessionID); err != nil {
315				fmt.Fprintf(errW, "Warning: could not check other sessions for shadow branch: %v\n", err)
316			} else if shouldDelete {
317				if err := strategy.DeleteBranchCLI(ctx, ss.ShadowBranch); err != nil {
318					// Branch already gone is not an error — keeps discard idempotent
319					if !errors.Is(err, strategy.ErrBranchNotFound) {
320						return fmt.Errorf("failed to delete shadow branch: %w", err)
321					}
322				}
323			}
324		}
325	
326		return nil
327	}
328	
329	// checkDisconnectedMetadata detects and optionally repairs disconnected
330	// local/remote metadata branches (the "empty-orphan bug").
331	func checkDisconnectedMetadata(cmd *cobra.Command, force bool) error {
332		repo, err := openRepository(cmd.Context())
333		if err != nil {
334			return fmt.Errorf("failed to open repository: %w", err)
335		}
336		defer repo.Close()
337	
338		ctx := cmd.Context()
339		remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
340		disconnected, err := strategy.IsMetadataDisconnected(ctx, repo, remoteRefName)
341		if err != nil {
342			return fmt.Errorf("could not check metadata branch state: %w", err)
343		}
344	
345		w := cmd.OutOrStdout()
346	
347		if !disconnected {
348			fmt.Fprintln(w, "✓ Metadata branches: OK")
349			return nil
350		}
351	
352		fmt.Fprintln(w, "Metadata branches: DISCONNECTED")
353		fmt.Fprintln(w, "  Local and remote entire/checkpoints/v1 branches share no common ancestor.")
354		fmt.Fprintln(w, "  Some remote checkpoints may not be visible locally.")
355		fmt.Fprintln(w, "  Fix: cherry-pick local checkpoints onto remote tip (preserves all data).")
356	
357		if !force {
358			var confirmed bool
359			form := NewAccessibleForm(
360				huh.NewGroup(
361					huh.NewConfirm().
362						Title("Fix disconnected metadata branches?").
363						Value(&confirmed),
364				),
365			)
366			if formErr := form.Run(); formErr != nil {
367				if errors.Is(formErr, huh.ErrUserAborted) {
368					return nil
369				}
370				return fmt.Errorf("prompt failed: %w", formErr)
371			}
372			if !confirmed {
373				fmt.Fprintln(w, "  -> Skipped")
374				return nil
375			}
376		}
377	
378		if fixErr := strategy.ReconcileDisconnectedMetadataBranch(ctx, repo, remoteRefName, cmd.ErrOrStderr()); fixErr != nil {
379			return fmt.Errorf("failed to reconcile metadata branches: %w", fixErr)
380		}
381	
382		fmt.Fprintln(w, "  ✓ Fixed: metadata branches reconciled")
383		return nil
384	}
385	
386	// checkCodexHookTrust warns about two kinds of drift in the Codex hook
387	// setup:
388	//
389	//  1. .codex/hooks.json is stale relative to what the CLI installs
390	//     today (e.g. a release added PostToolUse after the user enabled
391	//     Codex). Fix: re-run `entire enable`.
392	//
393	//  2. A declared hook lacks a `trusted_hash` entry in the user's Codex
394	//     config — either a fresh clone or a newer hook on the file the
395	//     user hasn't approved yet. Fix: open /hooks in Codex.
396	//
397	// Both checks are structural (file/key presence). Stays silent when
398	// this repo doesn't have codex hooks installed or when we can't
399	// resolve the worktree root. Warn-only.
400	func checkCodexHookTrust(cmd *cobra.Command) {
401		repoRoot, err := paths.WorktreeRoot(cmd.Context())
402		if err != nil {
403			return
404		}
405		if _, statErr := os.Stat(filepath.Join(repoRoot, ".codex", "hooks.json")); statErr != nil {
406			return
407		}
408	
409		w := cmd.OutOrStdout()
410		missing := codex.MissingEntireHooks(repoRoot)
411		gaps := codex.HookTrustGaps(repoRoot)
412	
413		if len(missing) == 0 && len(gaps) == 0 {
414			fmt.Fprintln(w, "✓ Codex hook trust: OK")
415			return
416		}
417	
418		if len(missing) > 0 {
419			fmt.Fprintln(w, "Codex hooks: OUT OF DATE")
420			fmt.Fprintf(w, "  %d hook(s) the CLI installs today aren't declared in .codex/hooks.json:\n", len(missing))
421			for _, ev := range missing {
422				fmt.Fprintf(w, "    - %s\n", ev)
423			}
424			fmt.Fprintln(w, "  Run `entire enable` to refresh the hooks file.")
425		}
426	
427		if len(gaps) > 0 {
428			fmt.Fprintln(w, "Codex hook trust: REVIEW NEEDED")
429			fmt.Fprintf(w, "  %d hook(s) declared in .codex/hooks.json have no trusted_hash entry yet:\n", len(gaps))
430			for _, ev := range gaps {
431				fmt.Fprintf(w, "    - %s\n", ev)
432			}
433			fmt.Fprintln(w, "  Open /hooks inside Codex to approve them.")
434		}
435	}
436	
437	// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
438	// Returns true if no other sessions (besides excludeSessionID) need this branch.
439	func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
440		states, err := strategy.ListSessionStates(ctx)
441		if err != nil {
442			return false, fmt.Errorf("failed to list session states: %w", err)
443		}
444	
445		for _, state := range states {
446			if state.SessionID == excludeSessionID {
447				continue
448			}
449			otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
450			if otherShadow == shadowBranch && state.StepCount > 0 {
451				return false, nil
452			}
453		}
454	
455		return true, nil
456	}
