152	func addDirToZip(zw *zip.Writer, srcDir, archivePrefix string, raw bool) error {
153		info, err := os.Stat(srcDir)
154		if err != nil {
155			if errors.Is(err, os.ErrNotExist) {
156				return nil
157			}
158			return fmt.Errorf("stat %s: %w", srcDir, err)
159		}
160		if !info.IsDir() {
161			return nil
162		}
163		walkErr := filepath.Walk(srcDir, func(path string, fi os.FileInfo, werr error) error {
164			if werr != nil {
165				return werr
166			}
167			if fi.IsDir() {
168				return nil
169			}
170			rel, err := filepath.Rel(srcDir, path)
171			if err != nil {
172				return fmt.Errorf("rel: %w", err)
173			}
174			return addFileToZip(zw, path, zipEntryName(archivePrefix, rel), raw)
175		})
176		if walkErr != nil {
177			return fmt.Errorf("walk %s: %w", srcDir, walkErr)
178		}
179		return nil
180	}
