	defer zr.Close()

	got := make(map[string]bool, len(zr.File))
	for _, f := range zr.File {
		if strings.Contains(f.Name, `\`) {
			t.Errorf("zip entry %q contains backslash path separator", f.Name)
		}
		got[f.Name] = true
